node << 'EOF'
const fs = require('fs');
const {execSync} = require('child_process');
function read(p){return JSON.parse(fs.readFileSync(p,'utf8'));}
const pkgs = [
  ['apps/frontend/package.json','@santan/frontend'],
  ['apps/studio/package.json','@santan/studio'],
  ['packages/shared/package.json','@santan/shared'],
  ['package.json','santan-monorepo'],
];
for (const [file, name] of pkgs) {
  const j = read(file);
  const deps = {...j.dependencies, ...j.devDependencies};
  console.log('\n==', file);
  for (const [dep, spec] of Object.entries(deps)) {
    if (spec === '*' || spec.startsWith('npm:') || !spec.startsWith('^')) {
      console.log(`  PIN ${dep}@${spec}`);
      continue;
    }
    let installed;
    try {
      const out = execSync(`npm ls ${dep} --depth=0 --json`, {encoding:'utf8', stdio:['ignore','pipe','ignore']});
      const tree = JSON.parse(out);
      const node = tree.dependencies?.[dep];
      installed = node?.version;
    } catch (e) {
      try {
        const out = e.stdout?.toString() || '';
        const tree = JSON.parse(out);
        installed = tree.dependencies?.[dep]?.version;
      } catch { installed = 'ERR'; }
    }
    const floor = spec.replace(/^\^/,'');
    const mark = installed && installed !== floor ? ' LAG' : '';
    if (mark) console.log(`  ${dep} spec ${spec} installed ${installed}${mark}`);
  }
}
EOF

